import Replicate from "replicate";

const derivative: Derivative = async ({ row, ref, db, storage, auth, logging }) => {
  try {
    logging.log('Starting the derivative function');
    //replicate key
    const replicateKey = await rowy.secrets.get("replicate");
    if (!replicateKey) {
      logging.error('replicate API key not found');
    }
    const replicate = new Replicate({
      auth: replicateKey,
    });


    // Check if index is valid
    if (!row.text || row.text.length === 0 || !row.speaker || row.speaker.length === 0) {
      logging.log("Row data not qualified to run. Index or speaker is invalid.");
      return null;
    }
    logging.log(`Row index and speaker are valid. Index: ${row.index}, Speaker: ${row.speaker}`);

    //Define data to call API
    const speakerData = row.speaker;
    const textData = row.text;
    logging.log(`Speaker data and text data retrieved for API call`);
    // Mapping from language name to language code
    const languageMap = {
      "English": "en",
      "Spanish": "es",
      "French": "fr",
      "German": "de",
      "Italian": "it",
      "Portuguese": "pt",
      "Polish": "pl",
      "Turkish": "tr",
      "Russian": "ru",
      "Dutch": "nl",
      "Czech": "cs",
      "Arabic": "ar",
      "Chinese": "zh",
      "Hungarian": "hu",
      "Korean": "ko",
      "Hindi": "hi"
      // Allowed values:en, es, fr, de, it, pt, pl, tr, ru, nl, cs, ar, zh, hu, ko, hi
    };
    // Convert language name to code, default to 'en' if not found
    const languageCode = languageMap[row.language] || 'en';


    // Set the model version and input parameters
    const prediction = await replicate.predictions.create({
      version: "684bc3855b37866c0c65add2ff39c78f3dea3f4ff103a436465326e0f438d55e",
      input: {
        text: textData,
        speaker: speakerData,
        language: languageCode
      },
      webhook: "https://rowy-hooks-pom6wvgduq-as.a.run.app/wh/voiceClone/wgyVEUzsgIK70ohKDMML",
      webhook_events_filter: ["completed"]
    });

    logging.log(`Prediction created with ID: ${prediction.id}`);
    await ref.update({ genJson: prediction });

    return {
      id: prediction.id,
      status: prediction.status
    };

  } catch (error) {
    logging.error('Error running the model:', error);
    return undefined;
  }
};
export default derivative;

const derivative: Derivative = async ({ row, ref, db, storage, auth }) => {
  if (row.genJson) {
    const genUrls = Array.isArray(row.genJson) ? row.genJson : [row.genJson];

    if (genUrls.length > 0) {
      const genUrl = genUrls[0];
      const genAudio = await rowy.storage.upload.url(genUrl, {
        folderPath: ref.path + '/voiceClone/'
      });
      return genAudio.downloadURL;
    } else {
      return null; // or any default value you prefer when no URLs are present
    }
  } else {
    return null; // or any default value you prefer when genImageJson is not present
  }
};

export default derivative;

