const basicParser: Parser = async ({ req, db, ref }) => {
    const { body } = req;
    // auditField
    const _updatedBy = await rowy.metadata.serviceAccountUser()
    const { id } = body
    const query = await ref.where("genJson.id", "==", id).get()
    if (query.empty) {
        return null
    } else {
        await query.docs[0].ref.update({ genJson: body.output, _updatedBy })
        return null
    }
}
